package com.exelynt.booking.service; import com.exelynt.booking.dto.*; import com.exelynt.booking.entity.Resource; import com.exelynt.booking.exception.ApiException; import com.exelynt.booking.repository.ResourceRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ResourceService {private final ResourceRepository repo; public ResourceService(ResourceRepository r){repo=r;} public List<ResourceResponse> all(){return repo.findAll().stream().map(this::map).toList();} public ResourceResponse one(Long id){return map(entity(id));} public ResourceResponse create(ResourceRequest r){Resource e=new Resource();copy(r,e);return map(repo.save(e));} public ResourceResponse update(Long id,ResourceRequest r){Resource e=entity(id);copy(r,e);return map(repo.save(e));} public void delete(Long id){repo.delete(entity(id));} private Resource entity(Long id){return repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Resource not found"));} private void copy(ResourceRequest r,Resource e){e.setName(r.name());e.setDescription(r.description());e.setType(r.type());e.setLocation(r.location());e.setPrice(r.price());e.setAvailable(r.available());} private ResourceResponse map(Resource e){return new ResourceResponse(e.getId(),e.getName(),e.getDescription(),e.getType(),e.getLocation(),e.getPrice(),e.isAvailable());}}
